mc_float_t mathAbsoluteFlt(const mc_float_t input)
{
    if(input < 0.0f)
    {
        return (-1.0f) * input;
    }
    else
    {
        return input;
    }
}

mc_float_t mathMergeFlt(mc_float_t desired, mc_float_t prev, mc_float_t step, mc_float_t *coeff)
{
    mc_float_t output;
    
    if(*coeff > 1)
    {
        *coeff = 1;
    }
    else
    {
        ;       /* do nothing */
    }
    output = *coeff * desired + (1 - *coeff) * prev;
    *coeff += step;
    
    if(output == desired)
    {
        coeff = 0;
    }
    else
    {
        ;       /* do nothing */
    }
    
    return output;
}

mc_float_t mathSinFlt(const mc_float_t angle)
{
    int i;
    
    i = (int)(angle * 2.0f);
    if(angle <  90)
    {
        return sin_arr[i];
    }
    else if(angle < 180)
    {
        return sin_arr[IDX180 - i];
    }
    else if(angle < 270)
    {
        return -sin_arr[i - IDX180];
    }
    else if(angle < 360)
    {
        return -sin_arr[IDX360 - i];
    }
    else
    {
        return 1.0f;
    }
}

mc_float_t mathCosFlt(const mc_float_t angle)
{
    int i;
    
    i = (int)(angle * 2.0f);
    if(angle <  90)
    {
        return sin_arr[IDX90 - i];
    }
    else if(angle < 180)
    {
        return -sin_arr[i - IDX90];
    }
    else if(angle < 270)
    {
        return -sin_arr[IDX270 - i];
    }
    else if(angle < 360)
    {
        return sin_arr[i - IDX270];
    }
    else
    {
        return 0.0f;
    }
}

void mathCalcSinCosFlt(const mc_float_t angle, mc_float_t *sin, mc_float_t *cos)
{
    int i;
    
    i = (int)(angle * 2.0f);
    if(angle <  90)
    {
        *sin = sin_arr[i];
        *cos = sin_arr[IDX90 - i];
    }
    else if(angle < 180)
    {
        *sin = sin_arr[IDX180 - i];
        *cos = -sin_arr[i - IDX90];
    }
    else if(angle < 270)
    {
        *sin = -sin_arr[i - IDX180];
        *cos = -sin_arr[IDX270 - i];
    }
    else if(angle < 360)
    {
        *sin = -sin_arr[IDX360 - i];
        *cos = sin_arr[i - IDX270];
    }
    else
    {
        *sin = 1.0f;
        *cos = 0.0f;
    }
}

mc_float_t mathTanFlt(const mc_float_t angle)
{
    int i;
    
    i = (int)(angle * 2.0f);
    if(angle <  90)
    {
        return tan_arr[i];
    }
    else if(angle < 180)
    {
        return -tan_arr[IDX180 - i];
    }
    else if(angle < 270)
    {
        return tan_arr[i - IDX180];
    }
    else if(angle < 360)
    {
        return -tan_arr[IDX360 - i];
    }
    else
    {
        return 1.0f;
    }
}

mc_float_t mathArcTanFlt(mc_float_t ampsin, mc_float_t ampcos)
{
    mc_int32_t indx = 0, indx_min, indx_max, indx_size;
    mc_float_t amp, tanx;
    mc_float_t deg = 0;
    
    if(ampcos == 0.0f)
        ampcos = 0.000000001f;
    tanx = ampsin / ampcos;
    amp = mathAbsoluteFlt(tanx);
    
    indx_size = sizeof(tan_arr) / sizeof(tan_arr[0]);
    indx_min = 0;
    indx_max = indx_size -1;
    indx = indx_size / 2;

    if(amp < tan_arr[indx_max])
    {
        while(indx != indx_min && indx < indx_size)
        {
            if(amp < tan_arr[indx])
            {
                indx_max = indx;
            }
            else if(amp > tan_arr[indx])
            {
                indx_min = indx;
            }
            else
            {
                ;       /* do nothing */
            }
            
            indx = indx_min + (indx_max - indx_min) / 2;        
        }
        
        if(indx < indx_size -1)
            deg = indx * 0.5f + 0.5f * (amp - tan_arr[indx]) / (tan_arr[indx+1] - tan_arr[indx]);
        else
            deg = 90.0f;
    }    
    else
    {
        ;       /* do nothing */
    }
    
    if(tanx < 0)
    {
        if(ampcos < 0)
        {
            deg = 180 - deg;
        }
        else
        {
            deg = -deg;
        }
    }
    else
    {
        if(ampcos < 0)
        {
            deg = (180 + deg) - 360.0f;
        }
        else
        {
            ;       /* do nothing */
        }        
    }

    return deg;
}

mc_float_t mathAngleSumDeg(const mc_float_t l_angle_deg_1, const mc_float_t l_angle_deg_2)
{
    mc_float_t l_angle_sum_deg;
    
    l_angle_sum_deg = l_angle_deg_1 + l_angle_deg_2;
    
    if (l_angle_sum_deg < 0.0f)
    {
        l_angle_sum_deg += MC_TWOPI2DEG;
    }
    else if (l_angle_sum_deg >= 360.0f)
    {
        l_angle_sum_deg -= MC_TWOPI2DEG;
    }
    else
    {
        ;  /* do nothing */
    }
    
    return l_angle_sum_deg;
}

mc_float_t mathCalculateRms(float value, sRmsCalc_t *rmsCalcObj, unsigned timeCnt)
{
    float value2;

    value2 = value * value;
    rmsCalcObj->v2sum += value2;
    rmsCalcObj->cntr++;	

    if(rmsCalcObj->prevTime != timeCnt)
    {
        rmsCalcObj->rms2 = rmsCalcObj->v2sum / rmsCalcObj->cntr;
	    rmsCalcObj->rms = sqrtf(rmsCalcObj->rms2);
        rmsCalcObj->v2sum = 0;
	rmsCalcObj->cntr = 0;
    }
    else
    {
	;	/* do nothing */
    }
    rmsCalcObj->prevTime = timeCnt;
	
    return 	rmsCalcObj->rms;
}

mc_float_t mathCalculateMax(float value, sMaxCalc_t *maxCalcObj, unsigned timeCnt)
{
    if(value > maxCalcObj->maxActual)
        maxCalcObj->maxActual = value;
    
    if(maxCalcObj->prevTime != timeCnt)
    {
        maxCalcObj->maxResult = maxCalcObj->maxActual;
        maxCalcObj->maxActual = 0;
    }
    else
    {
	;	/* do nothing */
    }
    maxCalcObj->prevTime = timeCnt;
	
    return 	maxCalcObj->maxResult;
}

mc_float_t mathCalculateAve(float value, sAveCalc_t *aveCalcObj, unsigned timeCnt)
{
    aveCalcObj->sum += value;
    aveCalcObj->cntr++;
    
    if(aveCalcObj->prevTime != timeCnt)
    {
        aveCalcObj->ave = aveCalcObj->sum / aveCalcObj->cntr;
        aveCalcObj->sum = 0;
	aveCalcObj->cntr = 0;
    }
    else
    {
	;	/* do nothing */
    }
    aveCalcObj->prevTime = timeCnt;
	
    return 	aveCalcObj->ave;
}
